
-- RemoteWay task, grading, earnings and withdrawal workflow.
-- The core application tables (profiles, jobs, applications, job_workspace_access,
-- job_network_profiles, payout_methods, payouts and admin_audit_logs) are provided
-- by the existing RemoteWay schema.
alter table public.job_workspace_access add column if not exists work_started_at timestamptz;
alter table public.payouts add column if not exists request_details jsonb not null default '{}'::jsonb;

create schema if not exists private;
create table if not exists public.job_task_templates (
  id bigint generated by default as identity primary key,
  job_id bigint not null references public.jobs(id) on delete cascade,
  title text not null,
  instructions text not null,
  task_type text not null default 'written' check(task_type in ('written','structured','file_upload','simulation')),
  max_reward numeric(10,2) not null default 0 check(max_reward between 0 and 200),
  estimated_minutes integer not null default 30 check(estimated_minutes between 1 and 1440),
  day_number integer not null check(day_number between 1 and 31),
  is_published boolean not null default false,
  is_simulated boolean not null default true,
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(job_id,day_number)
);
create table if not exists public.job_task_assignments (
  id bigint generated by default as identity primary key,
  application_id bigint not null references public.applications(id) on delete cascade,
  candidate_id uuid not null references public.profiles(id) on delete cascade,
  job_id bigint not null references public.jobs(id) on delete cascade,
  task_template_id bigint not null references public.job_task_templates(id) on delete cascade,
  assigned_date date not null,
  status text not null default 'available' check(status in ('available','submitted','graded','locked')),
  created_at timestamptz not null default now(),
  unique(application_id,task_template_id),
  unique(application_id,assigned_date,task_template_id)
);
create table if not exists public.job_task_submissions (
  id bigint generated by default as identity primary key,
  assignment_id bigint not null unique references public.job_task_assignments(id) on delete cascade,
  candidate_id uuid not null references public.profiles(id) on delete cascade,
  response jsonb not null default '{}'::jsonb,
  completion_percent numeric(5,2) not null default 0 check(completion_percent between 0 and 100),
  quality_score numeric(5,2) check(quality_score between 0 and 100),
  grade_band text check(grade_band in ('excellent','average','poor','invalid')),
  feedback text,
  reward_amount numeric(10,2) not null default 0 check(reward_amount between 0 and 200),
  status text not null default 'submitted' check(status in ('submitted','graded','needs_review','rejected')),
  submitted_at timestamptz not null default now(),
  graded_at timestamptz,
  graded_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);
create table if not exists public.job_earnings_ledger (
  id bigint generated by default as identity primary key,
  candidate_id uuid not null references public.profiles(id) on delete cascade,
  application_id bigint not null references public.applications(id) on delete cascade,
  submission_id bigint not null unique references public.job_task_submissions(id) on delete cascade,
  amount numeric(10,2) not null check(amount between 0 and 200),
  currency text not null default 'USD' check(currency='USD'),
  earning_date date not null default current_date,
  week_start date not null,
  week_end date not null,
  status text not null default 'approved' check(status in ('pending','approved','paid','reversed')),
  created_at timestamptz not null default now(),
  check(week_end=week_start+6)
);
create table if not exists private.job_task_answer_keys (
  task_template_id bigint primary key references public.job_task_templates(id) on delete cascade,
  required_keywords jsonb not null default '[]'::jsonb,
  minimum_words integer not null default 35 check(minimum_words between 1 and 5000),
  rubric jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);
alter table private.job_task_answer_keys enable row level security;
revoke all on private.job_task_answer_keys from anon,authenticated,public;
grant usage on schema private to service_role;
grant all on private.job_task_answer_keys to service_role;

alter table public.job_task_templates drop column if exists expected_output;
alter table public.job_task_templates drop column if exists grading_rubric;
alter table public.job_task_templates enable row level security;
alter table public.job_task_assignments enable row level security;
alter table public.job_task_submissions enable row level security;
alter table public.job_earnings_ledger enable row level security;
drop policy if exists "admins manage task templates" on public.job_task_templates;
drop policy if exists "published task templates visible to signed-in users" on public.job_task_templates;
drop policy if exists "admins manage task assignments" on public.job_task_assignments;
drop policy if exists "candidates view own task assignments" on public.job_task_assignments;
drop policy if exists "admins grade submissions" on public.job_task_submissions;
drop policy if exists "candidates submit own task work" on public.job_task_submissions;
drop policy if exists "candidates view own task submissions" on public.job_task_submissions;
drop policy if exists "admins manage earnings ledger" on public.job_earnings_ledger;
drop policy if exists "candidates view own earnings ledger" on public.job_earnings_ledger;
create policy "admins manage task templates" on public.job_task_templates for all to authenticated
 using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin')))
 with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin')));
create policy "published task templates visible to signed-in users" on public.job_task_templates for select to authenticated
 using(is_published=true or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin')));
create policy "admins manage task assignments" on public.job_task_assignments for all to authenticated
 using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin')))
 with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin')));
create policy "candidates view own task assignments" on public.job_task_assignments for select to authenticated
 using(candidate_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin')));
create policy "admins grade submissions" on public.job_task_submissions for all to authenticated
 using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin')))
 with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin')));
create policy "candidates view own task submissions" on public.job_task_submissions for select to authenticated
 using(candidate_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin')));
create policy "admins manage earnings ledger" on public.job_earnings_ledger for all to authenticated
 using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin')))
 with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin')));
create policy "candidates view own earnings ledger" on public.job_earnings_ledger for select to authenticated
 using(candidate_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin')));
revoke insert,update,delete on public.job_task_submissions from anon,authenticated;
grant select on public.job_task_templates,public.job_task_assignments,public.job_task_submissions,public.job_earnings_ledger to authenticated;
create index if not exists job_task_assignments_candidate_date_idx on public.job_task_assignments(candidate_id,assigned_date,status);
create index if not exists job_task_submissions_candidate_date_idx on public.job_task_submissions(candidate_id,submitted_at desc);
create index if not exists job_earnings_ledger_candidate_week_idx on public.job_earnings_ledger(candidate_id,week_start,status);
create index if not exists job_earnings_ledger_application_idx on public.job_earnings_ledger(application_id);
create index if not exists job_workspace_access_candidate_start_idx on public.job_workspace_access(candidate_id,work_started_at);

create or replace function public.remote_way_week_window(p_started_at timestamptz,p_reference timestamptz default now())
returns table(week_start date,week_end date,eligible_at timestamptz)
language sql immutable
set search_path=pg_catalog
as $$
 with start_day as (select (p_started_at at time zone 'UTC')::date as d),
 elapsed as (select d+(greatest(0,((p_reference at time zone 'UTC')::date-d)/7)*7) as ws from start_day)
 select ws,ws+6,((ws+7)::timestamp at time zone 'UTC') from elapsed;
$$;

create or replace function public.remote_way_get_task_answer_key(p_template_id bigint)
returns jsonb language sql security definer set search_path=public,private,pg_temp as $$
 select jsonb_build_object('required_keywords',k.required_keywords,'minimum_words',k.minimum_words,'rubric',k.rubric)
 from private.job_task_answer_keys k join public.job_task_templates t on t.id=k.task_template_id
 where k.task_template_id=p_template_id and t.is_published=true
$$;
revoke all on function public.remote_way_get_task_answer_key(bigint) from public,anon,authenticated;
grant execute on function public.remote_way_get_task_answer_key(bigint) to service_role;

create or replace function public.remote_way_record_task_submission(
 p_candidate_id uuid,p_assignment_id bigint,p_response text,p_completion numeric,p_quality numeric,p_grade_band text,p_feedback text
) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$
declare
 v_assignment public.job_task_assignments%rowtype; v_template public.job_task_templates%rowtype;
 v_submission_id bigint; v_start_date date; v_today date:=(now() at time zone 'UTC')::date;
 v_week_start date; v_week_end date; v_cap_remaining numeric; v_calculated numeric; v_reward numeric;
begin
 if p_candidate_id is null or p_assignment_id is null then raise exception 'Missing candidate or task.'; end if;
 if coalesce(length(trim(p_response)),0)<8 then raise exception 'Please provide a meaningful response before submitting.'; end if;
 if p_completion<0 or p_completion>100 or p_quality<0 or p_quality>100 then raise exception 'Invalid grading values.'; end if;
 if p_grade_band not in ('excellent','average','poor','invalid') then raise exception 'Invalid grade band.'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_candidate_id::text,0));
 select * into v_assignment from public.job_task_assignments where id=p_assignment_id and candidate_id=p_candidate_id for update;
 if not found then raise exception 'Task assignment not found.'; end if;
 if v_assignment.status<>'available' then raise exception 'This task has already been submitted or is no longer available.'; end if;
 if v_assignment.assigned_date>v_today then raise exception 'This task is not available yet.'; end if;
 select * into v_template from public.job_task_templates where id=v_assignment.task_template_id and is_published=true;
 if not found then raise exception 'Task instructions are no longer available.'; end if;
 select min(coalesce(work_started_at,created_at)::date) into v_start_date from public.job_workspace_access where candidate_id=p_candidate_id;
 if v_start_date is null then raise exception 'Your job start date is not recorded yet.'; end if;
 v_week_start:=v_start_date+(greatest(v_today-v_start_date,0)/7)*7; v_week_end:=v_week_start+6;
 select greatest(0,200-coalesce(sum(amount),0)) into v_cap_remaining from public.job_earnings_ledger
 where candidate_id=p_candidate_id and week_start=v_week_start and status<>'reversed';
 v_calculated:=round(v_template.max_reward*(p_completion/100)*(p_quality/100),2);
 if p_grade_band='invalid' then v_calculated:=0; end if;
 v_reward:=least(v_calculated,coalesce(v_cap_remaining,200));
 insert into public.job_task_submissions(assignment_id,candidate_id,response,completion_percent,quality_score,grade_band,feedback,reward_amount,status,graded_at)
 values(v_assignment.id,p_candidate_id,jsonb_build_object('text',p_response),p_completion,p_quality,p_grade_band,left(coalesce(p_feedback,''),2000),v_reward,'graded',now()) returning id into v_submission_id;
 if v_reward>0 then insert into public.job_earnings_ledger(candidate_id,application_id,submission_id,amount,currency,earning_date,week_start,week_end,status)
 values(p_candidate_id,v_assignment.application_id,v_submission_id,v_reward,'USD',v_today,v_week_start,v_week_end,'approved'); end if;
 update public.job_task_assignments set status='graded' where id=v_assignment.id;
 return jsonb_build_object('submission_id',v_submission_id,'assignment_id',v_assignment.id,'quality_score',p_quality,'completion_percent',p_completion,'grade_band',p_grade_band,'feedback',left(coalesce(p_feedback,''),2000),'reward_amount',v_reward,'week_start',v_week_start,'week_end',v_week_end);
end; $$;
revoke all on function public.remote_way_record_task_submission(uuid,bigint,text,numeric,numeric,text,text) from public,anon,authenticated;
grant execute on function public.remote_way_record_task_submission(uuid,bigint,text,numeric,numeric,text,text) to service_role;

drop function if exists public.remote_way_request_payout(uuid,numeric,bigint);
create or replace function public.remote_way_request_payout(p_candidate_id uuid,p_amount numeric,p_method_id bigint,p_details jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$
declare
 v_today date:=(now() at time zone 'UTC')::date; v_start_date date; v_eligible_at date;
 v_available numeric; v_reserved numeric; v_payout_id bigint; v_details jsonb:=coalesce(p_details,'{}'::jsonb);
begin
 if p_candidate_id is null then raise exception 'Sign in to request a withdrawal.'; end if;
 if p_amount is null or p_amount<1 or p_amount<>round(p_amount,2) then raise exception 'Enter a withdrawal amount of at least $1.00.'; end if;
 if jsonb_typeof(v_details)<>'object' or pg_column_size(v_details)>12000 then raise exception 'Withdrawal details are invalid or too large.'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_candidate_id::text,0));
 if not exists(select 1 from public.payout_methods where id=p_method_id and user_id=p_candidate_id and status='active') then raise exception 'Save an active payout method before requesting a withdrawal.'; end if;
 select min(coalesce(work_started_at,created_at)::date) into v_start_date from public.job_workspace_access where candidate_id=p_candidate_id;
 if v_start_date is null then raise exception 'Your job start date is not recorded yet.'; end if;
 v_eligible_at:=v_start_date+7;
 if v_today<v_eligible_at then raise exception 'Your first payout period has not closed yet. Eligibility begins on %.',v_eligible_at; end if;
 select coalesce(sum(amount),0) into v_available from public.job_earnings_ledger where candidate_id=p_candidate_id and status='approved' and week_end<v_today;
 select coalesce(sum(amount),0) into v_reserved from public.payouts where user_id=p_candidate_id and status in ('pending','processing','paid');
 v_available:=greatest(0,v_available-v_reserved);
 if p_amount>v_available then raise exception 'The requested amount exceeds your available balance of $%.',to_char(v_available,'FM999999990.00'); end if;
 insert into public.payouts(user_id,payout_method_id,amount,currency,status,request_details) values(p_candidate_id,p_method_id,round(p_amount,2),'USD','pending',v_details) returning id into v_payout_id;
 return jsonb_build_object('id',v_payout_id,'amount',round(p_amount,2),'currency','USD','status','pending','created_at',now(),'eligible_at',v_eligible_at,'estimated_processing_days','4–5 working days');
end; $$;
revoke all on function public.remote_way_request_payout(uuid,numeric,bigint,jsonb) from public,anon,authenticated;
grant execute on function public.remote_way_request_payout(uuid,numeric,bigint,jsonb) to service_role;

