  job_id bigint,day_number integer,title text,instructions text,task_type text,max_reward numeric,estimated_minutes integer,
  is_published boolean,is_simulated boolean,required_keywords jsonb,minimum_words integer,rubric jsonb
 )
), upserted as (
 insert into public.job_task_templates(job_id,title,instructions,task_type,max_reward,estimated_minutes,day_number,is_published,is_simulated)
 select job_id,title,instructions,task_type,max_reward,estimated_minutes,day_number,is_published,is_simulated from src
 on conflict(job_id,day_number) do update set title=excluded.title,instructions=excluded.instructions,task_type=excluded.task_type,
 max_reward=excluded.max_reward,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,
 is_simulated=excluded.is_simulated,updated_at=now()
 returning id,job_id,day_number
)
insert into private.job_task_answer_keys(task_template_id,required_keywords,minimum_words,rubric)
select u.id,src.required_keywords,src.minimum_words,src.rubric from upserted u join src using(job_id,day_number)
on conflict(task_template_id) do update set required_keywords=excluded.required_keywords,minimum_words=excluded.minimum_words,rubric=excluded.rubric,updated_at=now();

drop index if exists public.job_earnings_candidate_week_idx;
